def minimumTime(time: list[int], totalTrips: int) -> int:
    lo, hi = 1, min(time) * totalTrips
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        trips = sum(mid // t for t in time)
        if trips >= totalTrips:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

